// stuckcheck demo: renders site/data.json (generated by scripts/export_site_data.py).
(function () {
  "use strict";

  // ---- Cause names + one-line meaning (group decides badge style) ----
  var CAUSES = {
    already_paid:     { name: "Already paid",      group: "stuck",  desc: "Customer says it paid; the cash is not matched on our ledger yet." },
    short_paid:       { name: "Short-paid",        group: "stuck",  desc: "Paid less than invoiced, or disputes the amount." },
    portal_rejected:  { name: "Portal rejected",   group: "stuck",  desc: "The customer's AP portal (Coupa, Ariba, Tungsten...) bounced the invoice." },
    missing_po:       { name: "Missing PO",        group: "stuck",  desc: "AP cannot process it without a purchase order number." },
    contact_left:     { name: "AP contact left",   group: "stuck",  desc: "Our AP contact is gone or the mailbox bounces." },
    approval_stalled: { name: "Approval stalled",  group: "stuck",  desc: "The invoice is sitting with an approver." },
    never_received:   { name: "Never received",    group: "stuck",  desc: "The customer has no copy of the invoice." },
    promise_broken:   { name: "Promise broken",    group: "stuck",  desc: "A promised pay date has passed with no cash." },
    genuinely_slow:   { name: "Genuinely slow",    group: "slow",   desc: "Not stuck: the customer is short on cash and asks for time." },
    no_reply:         { name: "No reply",          group: "slow",   desc: "We chased and the customer has not answered." },
    needs_review:     { name: "Needs review",      group: "review", desc: "Customer replied, but no rule matched. A person reads it; no draft is written." }
  };
  var ORDER = Object.keys(CAUSES);

  var state = { data: null, filter: "all", q: "", sort: "open", selected: null };
  var $ = function (id) { return document.getElementById(id); };
  var money = function (x) { return "$" + Math.round(x).toLocaleString("en-US"); };
  var esc = function (s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  };
  var isNarrow = function () { return window.matchMedia("(max-width: 960px)").matches; };
  var badge = function (cause) {
    var c = CAUSES[cause];
    return '<span class="badge ' + c.group + '">' + esc(c.name) + "</span>";
  };
  var custName = function (s) {
    return esc(s).replace(" (synthetic)", ' <span class="syn">(synthetic)</span>');
  };

  // ---- Evidence strings from the classifier -> structured pieces ----
  var EV_RE = /^(customer|system) \((\d+)d ago\): '(.+)' -> (\w+)$/;
  function parseEv(s) {
    var m = s.match(EV_RE);
    if (m) return { kind: "text", who: m[1], days: +m[2], phrase: m[3], label: m[4] };
    if (s.indexOf("ledger: ") === 0) {
      var t = s.slice(8).replace(/paid ([\d.]+) of ([\d.]+)/, function (_, a, b) { return "paid " + money(+a) + " of " + money(+b); });
      return { kind: "ledger", text: "Ledger: " + t };
    }
    if (s.indexOf("thread: ") === 0) return { kind: "thread", text: s.slice(8) };
    return { kind: "note", text: s };
  }
  var LEDGER_FOR = { short_paid: "paid ", contact_left: "bounced", promise_broken: "promise" };
  function topEvidence(inv) {
    var evs = inv.evidence.map(parseEv);
    for (var i = 0; i < evs.length; i++) {
      var e = evs[i];
      if (e.kind === "ledger" && LEDGER_FOR[inv.cause] && e.text.indexOf(LEDGER_FOR[inv.cause]) > -1) return e;
    }
    for (i = 0; i < evs.length; i++) if (evs[i].kind === "text" && evs[i].label === inv.cause) return evs[i];
    return evs[0];
  }
  function evHtml(e) {
    if (!e) return "";
    if (e.kind === "text") return "<q>" + esc(e.phrase) + '</q> <span class="src">' + e.who + ", " + e.days + "d ago</span>";
    var t = e.text;
    if (e.kind === "note") t = "Customer replied; no known cause matched";
    return esc(t.charAt(0).toUpperCase() + t.slice(1));
  }

  // ---- KPIs ----
  function renderKpis() {
    var d = state.data, s = d.summary, cc = s.cause_counts;
    var hold = d.evaluation.filter(function (e) { return e.set === "holdout_set.json"; })[0];
    var wrongSure = hold.misses.filter(function (m) { return m.pred !== "needs_review"; }).length;
    var slow = (cc.genuinely_slow || 0) + (cc.no_reply || 0);
    var pct = Math.round(100 * s.stuck_open / s.open_total);
    $("kpis").innerHTML =
      '<div class="kpi primary"><div class="kpi-label">Stuck on a fixable blocker</div>' +
      '<div class="kpi-value">' + s.stuck_count + ' <small>of ' + s.invoices + ' overdue invoices</small></div>' +
      '<div class="kpi-sub">' + money(s.stuck_open) + " open of " + money(s.open_total) + " overdue (" + pct + "%)</div>" +
      '<div class="meter" aria-hidden="true"><span style="width:' + pct + '%"></span></div></div>' +
      '<div class="kpi"><div class="kpi-label">Needs human read</div><div class="kpi-value">' + s.needs_review +
      ' <small>invoices</small></div><div class="kpi-sub">No rule matched, so no draft</div></div>' +
      '<div class="kpi"><div class="kpi-label">Slow or silent</div><div class="kpi-value">' + slow +
      ' <small>invoices</small></div><div class="kpi-sub">Payment plan or a new channel</div></div>' +
      '<div class="kpi"><div class="kpi-label">Holdout accuracy</div><div class="kpi-value">' + hold.correct + "/" + hold.n +
      ' <small>(' + Math.round(100 * hold.correct / hold.n) + '%)</small></div><div class="kpi-sub">' + wrongSure +
      " wrong labels; misses go to review</div></div>";
  }

  // ---- Cause chips (labelled counts + filter) ----
  function renderChips() {
    var cc = state.data.summary.cause_counts;
    var html = chip("all", "All invoices", state.data.summary.invoices, null);
    html += chip("stuck", "All stuck", state.data.summary.stuck_count, "stuck");
    html += '<span class="chip-sep" aria-hidden="true"></span>';
    ORDER.forEach(function (k) { if (cc[k]) html += chip(k, CAUSES[k].name, cc[k], CAUSES[k].group); });
    $("chips").innerHTML = html;
    function chip(key, label, n, group) {
      var on = state.filter === key;
      return '<button class="chip' + (on ? " active" : "") + '" role="tab" aria-selected="' + on + '" data-f="' + key + '">' +
        (group ? '<span class="dot ' + group + '"></span>' : "") + esc(label) + ' <span class="n">' + n + "</span></button>";
    }
  }

  // ---- Table / cards ----
  function visible() {
    var q = state.q.trim().toLowerCase();
    var rows = state.data.invoices.filter(function (r) {
      if (state.filter === "stuck" && !r.stuck) return false;
      if (state.filter !== "all" && state.filter !== "stuck" && r.cause !== state.filter) return false;
      return !q || (r.customer + " " + r.id).toLowerCase().indexOf(q) > -1;
    });
    rows.sort(function (a, b) {
      if (state.sort === "dpd") return b.days_past_due - a.days_past_due;
      if (state.sort === "customer") return a.customer.localeCompare(b.customer);
      return b.open - a.open;
    });
    return rows;
  }
  function renderRows() {
    var rows = visible();
    $("rows").innerHTML = rows.map(function (r) {
      return '<tr class="row' + (r.id === state.selected ? " selected" : "") + '" tabindex="0" data-id="' + r.id + '">' +
        '<td class="c-cust"><div class="cust">' + custName(r.customer) + '</div><div class="cust-sub">' + r.id + "</div></td>" +
        '<td class="num c-open">' + money(r.open) + "</td>" +
        '<td class="num c-dpd"><span class="dpd' + (r.days_past_due >= 45 ? " hot" : "") + '">' + r.days_past_due + "</span></td>" +
        '<td class="c-cause">' + badge(r.cause) + "</td>" +
        '<td class="ev c-ev">' + evHtml(topEvidence(r)) + "</td>" +
        '<td class="chev" aria-hidden="true">&rsaquo;</td></tr>';
    }).join("");
    $("empty").hidden = rows.length > 0;
    var total = rows.reduce(function (a, r) { return a + r.open; }, 0);
    $("listfoot").textContent = "Showing " + rows.length + " of " + state.data.invoices.length +
      " invoices · " + money(total) + " open · synthetic data, as of " + state.data.as_of;
  }

  // ---- Detail panel: evidence, thread, draft email ----
  function highlight(text, phrases) {
    var out = esc(text);
    phrases.forEach(function (p) {
      var i = out.toLowerCase().indexOf(esc(p).toLowerCase());
      if (i > -1) out = out.slice(0, i) + "<mark>" + out.slice(i, i + esc(p).length) + "</mark>" + out.slice(i + esc(p).length);
    });
    return out;
  }
  function renderDetail() {
    var el = $("detail");
    var r = state.data.invoices.filter(function (x) { return x.id === state.selected; })[0];
    if (!r) {
      el.innerHTML = '<div class="d-sec"><p class="no-thread">Select an invoice to see why it is stuck and the follow-up drafted for it.</p></div>';
      return;
    }
    var c = CAUSES[r.cause];
    var evs = r.evidence.map(parseEv);
    var evItems = evs.map(function (e) {
      if (e.kind === "text") return "<li><b>" + (e.who === "system" ? "Portal notice" : "Customer") + ", " + e.days + "d ago:</b> " +
        "<q>" + esc(e.phrase) + "</q> points to " + esc(CAUSES[e.label].name) + "</li>";
      return "<li>" + evHtml(e) + "</li>";
    }).join("");
    var hand = "";
    if (r.hand_label) {
      var ok = r.hand_label === r.cause;
      hand = '<div class="hand">Hand label in holdout set: ' + esc(CAUSES[r.hand_label].name) + " · " +
        (ok ? '<span class="ok">tool agrees</span>' : '<span class="miss">tool missed this one</span>') + "</div>";
    }
    var phrasesFor = function (m) {
      return evs.filter(function (e) { return e.kind === "text" && e.who === m.from && e.days === m.days_ago; })
        .map(function (e) { return e.phrase; });
    };
    var thread = r.thread.length ? '<div class="thread">' + r.thread.map(function (m) {
      var who = m.from === "us" ? "You" : m.from === "system" ? "AP portal" : "Customer";
      return '<div class="msg ' + m.from + '"><div class="who">' + who + " · " + m.days_ago + "d ago</div>" +
        highlight(m.text, phrasesFor(m)) + "</div>";
    }).join("") + "</div>" : '<p class="no-thread">No email thread on file.</p>';

    var d = r.draft, isPlaceholder = r.cause === "needs_review";
    var body = isPlaceholder ? "No draft. The rules could not tell why this invoice is late, so a person reads the thread first." : d.body;

    el.innerHTML =
      '<div class="d-head"><div class="d-top"><span class="d-id">' + r.id + " · due " + r.due_date + "</span>" +
      '<button class="d-close" id="dclose">Close</button></div>' +
      '<div class="d-cust">' + custName(r.customer) + "</div>" +
      '<div class="d-facts">' +
      '<div class="fact"><div class="fact-l">Open</div><div class="fact-v">' + money(r.open) + "</div></div>" +
      '<div class="fact"><div class="fact-l">Invoiced</div><div class="fact-v">' + money(r.amount) + "</div></div>" +
      '<div class="fact"><div class="fact-l">Days overdue</div><div class="fact-v">' + r.days_past_due + "</div></div>" +
      "</div></div>" +
      '<div class="d-sec"><h3><span class="step">1</span>Why it\'s stuck</h3>' +
      '<div class="cause-line">' + badge(r.cause) + (isPlaceholder ? "" : '<span class="conf">score share ' + Math.round(r.confidence * 100) + "%</span>") + "</div>" +
      '<p class="cause-desc">' + esc(c.desc) + "</p>" +
      '<ul class="evlist">' + evItems + "</ul>" + hand + "</div>" +
      '<div class="d-sec"><h3><span class="step">2</span>Follow-up draft</h3>' +
      '<div class="composer">' +
      '<div class="comp-row"><span class="k">To</span><span class="v">AP contact, ' + esc(r.customer) + "</span></div>" +
      '<div class="comp-row"><span class="k">Subject</span><span class="v">' + esc(d.subject) + "</span></div>" +
      '<div class="comp-body' + (isPlaceholder ? " placeholder" : "") + '">' + esc(body) + "</div>" +
      '<div class="comp-actions">' +
      (isPlaceholder ? "" : '<button class="btn primary" id="copy">Copy draft</button>') +
      '<span class="comp-note">Draft only. Nothing is sent from this page.</span></div></div>' +
      '<div class="nextstep" style="margin-top:10px"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M4 10h11M11 5l5 5-5 5"/></svg>' +
      "<div><b>Internal next step:</b> " + esc(d.next_step) + "</div></div></div>" +
      '<div class="d-sec"><h3><span class="step">3</span>Email thread it was read from</h3>' + thread + "</div>";

    var copy = $("copy");
    if (copy) copy.onclick = function () {
      var txt = "Subject: " + d.subject + "\n\n" + d.body;
      var done = function () { toast("Draft copied"); };
      if (navigator.clipboard) navigator.clipboard.writeText(txt).then(done, function () { toast("Copy blocked by browser"); });
    };
    $("dclose").onclick = closeDetail;
  }

  function toast(msg) {
    var t = document.createElement("div");
    t.className = "toast"; t.textContent = msg;
    document.body.appendChild(t);
    setTimeout(function () { t.remove(); }, 1600);
  }

  function select(id, scroll) {
    state.selected = id;
    try { history.replaceState(null, "", "#" + id); } catch (e) { /* file:// */ }
    renderRows();
    renderDetail();
    $("detail").scrollTop = 0;
    if (isNarrow()) { $("detail").classList.add("open"); $("scrim").hidden = false; document.body.style.overflow = "hidden"; }
    else if (scroll) $("detail").scrollIntoView({ block: "nearest" });
  }
  function closeDetail() {
    $("detail").classList.remove("open");
    $("scrim").hidden = true;
    document.body.style.overflow = "";
  }

  function bind() {
    $("chips").addEventListener("click", function (e) {
      var b = e.target.closest(".chip"); if (!b) return;
      state.filter = b.getAttribute("data-f");
      renderChips(); renderRows();
    });
    $("rows").addEventListener("click", function (e) {
      var tr = e.target.closest("tr.row"); if (tr) select(tr.getAttribute("data-id"));
    });
    $("rows").addEventListener("keydown", function (e) {
      if (e.key !== "Enter" && e.key !== " ") return;
      var tr = e.target.closest("tr.row"); if (tr) { e.preventDefault(); select(tr.getAttribute("data-id")); }
    });
    $("q").addEventListener("input", function (e) { state.q = e.target.value; renderRows(); });
    $("sort").addEventListener("change", function (e) { state.sort = e.target.value; renderRows(); });
    $("clear").addEventListener("click", function () { state.filter = "all"; state.q = ""; $("q").value = ""; renderChips(); renderRows(); });
    $("scrim").addEventListener("click", closeDetail);
    document.addEventListener("keydown", function (e) { if (e.key === "Escape") closeDetail(); });
  }

  fetch("data.json").then(function (r) { return r.json(); }).then(function (data) {
    state.data = data;
    $("asof").textContent = data.as_of;
    var dev = data.evaluation[0], hold = data.evaluation[1];
    $("evaltext").innerHTML = "Holdout set: <b>" + hold.correct + "/" + hold.n + "</b> correct. Its cases were written before the rules were first run, and the rules were not tuned on it. " +
      "All " + hold.misses.length + " misses went to <em>Needs review</em>, not to a wrong label. Dev set: " + dev.correct + "/" + dev.n +
      " (written alongside the rules, so not a real accuracy figure).";
    renderKpis(); renderChips(); bind();
    var hashId = location.hash.slice(1);
    var first = visible()[0];
    state.selected = data.invoices.some(function (x) { return x.id === hashId; }) ? hashId : (isNarrow() ? null : first.id);
    renderRows(); renderDetail();
    if (hashId && isNarrow() && state.selected) select(state.selected);
  }).catch(function (err) {
    $("rows").innerHTML = '<tr><td colspan="6">Could not load data.json (' + esc(err.message) + ")</td></tr>";
  });
})();
